const [open, setOpen] = useState(false);
const handleClose = (trigger) => {
  // trigger values: "closeButton" | "backdropClick" | "keyboardEscape" | "unknown"
  console.log("Closed due to:", trigger);
  setOpen(false);
};

return (
  <ODSDialog open={open} onOpenChange={handleOpenChange} onClose={handleClose}>
    <ODSButton label="Open" onClick={() => setOpen(true)} />
    <ODSDialogContent
      headerText="Controlled example"
      actionSlot={
        <ODSDialogSheetPreferredActions
          mainActionProps={{ label: "OK", size: "small", onClick: handleClose }}
          secondaryActionProps={{
            label: "Cancel",
            size: "small",
            onClick: () => setOpen(false),
          }}
          variant="sideBySide"
        />
      }
    />
  </ODSDialog>
);
